  <style>
    /* ── Hero ── */
    .hero {
      position: relative;
      min-height: 92vh;
      display: flex;
      align-items: center;
      background: linear-gradient(135deg, #0D1B2A 0%, #15295A 50%, #0D1B2A 100%);
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%236CC24A' fill-opacity='0.04'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .hero-grid-overlay {
      position: absolute;
      inset: 0;
      background-image: linear-gradient(rgba(108,194,74,0.06) 1px, transparent 1px),
                        linear-gradient(90deg, rgba(108,194,74,0.06) 1px, transparent 1px);
      background-size: 60px 60px;
    }
    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 800px;
    }
    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(108,194,74,0.12);
      border: 1px solid rgba(108,194,74,0.3);
      border-radius: 100px;
      padding: 6px 16px;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: #6CC24A;
      margin-bottom: 24px;
    }
    .hero-eyebrow::before {
      content: '';
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #6CC24A;
      animation: pulse-dot 2s infinite;
    }
    @keyframes pulse-dot {
      0%,100% { opacity: 1; } 50% { opacity: 0.3; }
    }
    .hero h1 {
      font-size: clamp(2.2rem, 5vw, 3.8rem);
      font-weight: 800;
      line-height: 1.1;
      color: #ffffff;
      margin-bottom: 24px;
      letter-spacing: -0.02em;
    }
    .hero h1 span { color: #6CC24A; }
    .hero p {
      font-size: 1.15rem;
      color: rgba(255,255,255,0.72);
      line-height: 1.7;
      max-width: 580px;
      margin-bottom: 40px;
    }
    .hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-visual {
      position: absolute;
      right: 0;
      top: 50%;
      transform: translateY(-50%);
      width: 45%;
      max-width: 600px;
      opacity: 0.15;
      pointer-events: none;
    }

    /* ── Featured Product Banner ── */
    .product-banner {
      background: linear-gradient(90deg, #15295A 0%, #1B3A6B 50%, #0D1B2A 100%);
      border-top: 1px solid rgba(108,194,74,0.2);
      border-bottom: 1px solid rgba(108,194,74,0.2);
      padding: 20px 0;
    }
    .product-banner-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
    }
    .product-badge {
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .product-badge-icon {
      width: 48px;
      height: 48px;
      border-radius: 10px;
      background: linear-gradient(135deg, #6CC24A, #4a9e35);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .product-badge-text span {
      display: block;
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: #6CC24A;
    }
    .product-badge-text strong {
      font-size: 1.1rem;
      font-weight: 700;
      color: #fff;
    }

    /* ── Use Cases ── */
    .section-eyebrow {
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: #6CC24A;
      margin-bottom: 12px;
    }
    .use-cases-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 24px;
      margin-top: 48px;
    }
    .use-case-card {
      background: rgba(255,255,255,0.03);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 12px;
      padding: 28px;
      cursor: pointer;
      transition: all 0.22s ease;
      position: relative;
      overflow: hidden;
    }
    .use-case-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 2px;
      background: linear-gradient(90deg, #6CC24A, transparent);
      opacity: 0;
      transition: opacity 0.22s ease;
    }
    .use-case-card:hover {
      background: rgba(108,194,74,0.06);
      border-color: rgba(108,194,74,0.25);
      transform: translateY(-2px);
    }
    .use-case-card:hover::before { opacity: 1; }
    .use-case-icon {
      width: 44px;
      height: 44px;
      border-radius: 10px;
      background: rgba(108,194,74,0.12);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 16px;
    }
    .use-case-card h3 {
      font-size: 1rem;
      font-weight: 600;
      color: #fff;
      margin-bottom: 10px;
    }
    .use-case-card p {
      font-size: 0.875rem;
      color: rgba(255,255,255,0.55);
      line-height: 1.6;
    }

    /* ── Industry Tabs ── */
    .industry-tabs-section { background: #0D1B2A; }
    .tab-nav {
      display: flex;
      gap: 4px;
      background: rgba(255,255,255,0.04);
      border-radius: 10px;
      padding: 4px;
      flex-wrap: wrap;
      margin-bottom: 32px;
    }
    .tab-btn {
      flex: 1;
      min-width: 80px;
      padding: 10px 20px;
      border: none;
      background: transparent;
      color: rgba(255,255,255,0.55);
      font-family: inherit;
      font-size: 0.875rem;
      font-weight: 500;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.2s ease;
      white-space: nowrap;
    }
    .tab-btn.active {
      background: #15295A;
      color: #fff;
      box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    }
    .tab-btn:hover:not(.active) { color: #fff; background: rgba(255,255,255,0.06); }
    .tab-panel { display: none; }
    .tab-panel.active { display: block; animation: fadeIn 0.25s ease; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
    .industry-panel-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
      align-items: start;
    }
    .industry-panel-content h3 {
      font-size: 1.6rem;
      font-weight: 700;
      color: #fff;
      margin-bottom: 16px;
    }
    .industry-panel-content p {
      color: rgba(255,255,255,0.65);
      line-height: 1.7;
      margin-bottom: 24px;
    }
    .industry-products {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }
    .product-chip {
      background: rgba(108,194,74,0.1);
      border: 1px solid rgba(108,194,74,0.25);
      border-radius: 100px;
      padding: 5px 14px;
      font-size: 0.78rem;
      font-weight: 500;
      color: #6CC24A;
    }
    .industry-panel-visual {
      background: rgba(21,41,90,0.5);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 16px;
      padding: 32px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .data-row {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px;
      background: rgba(255,255,255,0.04);
      border-radius: 8px;
    }
    .data-row-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #6CC24A;
      flex-shrink: 0;
    }
    .data-row-label { font-size: 0.82rem; color: rgba(255,255,255,0.7); flex: 1; }
    .data-row-value { font-size: 0.82rem; font-weight: 600; color: #6CC24A; }

    /* ── Platform Ecosystem Diagram ── */
    .platform-diagram-section {
      background: linear-gradient(180deg, #0D1B2A 0%, #111c2e 100%);
    }
    .ecosystem-diagram {
      position: relative;
      max-width: 800px;
      margin: 0 auto;
    }
    .ecosystem-center {
      width: 160px;
      height: 160px;
      border-radius: 50%;
      background: linear-gradient(135deg, #15295A, #1B3A6B);
      border: 2px solid rgba(108,194,74,0.4);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      margin: 0 auto 0;
      position: relative;
      z-index: 2;
      box-shadow: 0 0 60px rgba(108,194,74,0.15);
    }
    .ecosystem-center span:first-child {
      font-size: 0.65rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: #6CC24A;
    }
    .ecosystem-center strong {
      font-size: 1.1rem;
      font-weight: 700;
      color: #fff;
      text-align: center;
      line-height: 1.2;
    }
    .ecosystem-pillars {
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      gap: 0;
      align-items: center;
      margin-top: 0;
    }
    .ecosystem-pillar {
      background: rgba(21,41,90,0.4);
      border: 1px solid rgba(108,194,74,0.2);
      border-radius: 14px;
      padding: 24px;
      text-align: center;
      position: relative;
    }
    .ecosystem-pillar h4 {
      font-size: 0.92rem;
      font-weight: 700;
      color: #fff;
      margin-bottom: 8px;
    }
    .ecosystem-pillar p {
      font-size: 0.78rem;
      color: rgba(255,255,255,0.55);
      line-height: 1.5;
    }
    .ecosystem-pillar-icon {
      width: 40px;
      height: 40px;
      border-radius: 10px;
      background: rgba(108,194,74,0.12);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 12px;
    }
    .ecosystem-connector {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
    }
    .connector-line {
      width: 2px;
      height: 40px;
      background: linear-gradient(180deg, rgba(108,194,74,0.5), transparent);
    }
    .connector-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      border: 2px solid #6CC24A;
      background: #0D1B2A;
    }

    /* ── Full ecosystem ── */
    .ecosystem-wrap {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0;
    }
    .ecosystem-top { margin-bottom: -1px; }
    .ecosystem-mid {
      display: grid;
      grid-template-columns: 1fr 160px 1fr;
      gap: 0;
      align-items: center;
      width: 100%;
      max-width: 760px;
    }
    .h-connector {
      height: 2px;
      background: linear-gradient(90deg, transparent, rgba(108,194,74,0.4), transparent);
    }
    .ecosystem-bottom { margin-top: 0; display: flex; gap: 24px; justify-content: center; }
    .pillar-bottom {
      flex: 1;
      max-width: 220px;
    }
    .v-connector-wrap {
      display: flex;
      justify-content: center;
    }
    .v-connector {
      width: 2px;
      height: 40px;
      background: linear-gradient(180deg, rgba(108,194,74,0.4), transparent);
    }

    /* ── Company Culture ── */
    .culture-section {
      background: linear-gradient(135deg, #15295A 0%, #0D1B2A 60%);
      border-top: 1px solid rgba(108,194,74,0.15);
    }
    .culture-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .culture-stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
    }
    .culture-stat {
      background: rgba(255,255,255,0.04);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 12px;
      padding: 20px;
    }
    .culture-stat-num {
      font-size: 2rem;
      font-weight: 800;
      color: #6CC24A;
      line-height: 1;
      margin-bottom: 4px;
    }
    .culture-stat-label {
      font-size: 0.8rem;
      color: rgba(255,255,255,0.55);
    }

    /* ── Renewables CTA ── */
    .renewables-section {
      background: linear-gradient(90deg, #0D1B2A 0%, #1a2e1a 100%);
      border-top: 1px solid rgba(108,194,74,0.15);
      border-bottom: 1px solid rgba(108,194,74,0.15);
    }
    .renewables-inner {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      align-items: center;
    }
    .renewables-inner h2 { font-size: 1.8rem; font-weight: 700; color: #fff; margin-bottom: 12px; }
    .renewables-inner p { color: rgba(255,255,255,0.65); line-height: 1.7; }

    /* ── Cookie Banner ── */
    .cookie-banner {
      position: fixed;
      bottom: 24px;
      left: 24px;
      right: 24px;
      max-width: 480px;
      background: #1B2838;
      border: 1px solid rgba(108,194,74,0.25);
      border-radius: 16px;
      padding: 24px;
      z-index: 999;
      box-shadow: 0 20px 60px rgba(0,0,0,0.5);
      transition: all 0.35s ease;
    }
    .cookie-banner.hidden {
      opacity: 0;
      pointer-events: none;
      transform: translateY(16px);
    }
    .cookie-banner h4 { font-size: 0.95rem; font-weight: 600; color: #fff; margin-bottom: 8px; }
    .cookie-banner p { font-size: 0.82rem; color: rgba(255,255,255,0.6); line-height: 1.5; margin-bottom: 16px; }
    .cookie-btns { display: flex; gap: 10px; }

    @media (max-width: 768px) {
      .hero-visual { display: none; }
      .use-cases-grid { grid-template-columns: 1fr; }
      .industry-panel-grid { grid-template-columns: 1fr; }
      .culture-grid { grid-template-columns: 1fr; gap: 40px; }
      .renewables-inner { grid-template-columns: 1fr; }
      .ecosystem-mid { grid-template-columns: 1fr; }
      .h-connector { display: none; }
      .ecosystem-bottom { flex-direction: column; align-items: center; }
      .cookie-banner { left: 12px; right: 12px; }
    }
  </style>
</head>
