/* ── WellStream Platform — Shared Styles ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:        #0D1B2A;
  --navy-mid:    #15295A;
  --navy-light:  #1B2838;
  --green:       #6CC24A;
  --green-dark:  #4a9e35;
  --gray-dark:   #3C424B;
  --text-primary: #ffffff;
  --text-muted:  rgba(255,255,255,0.6);
  --border:      rgba(255,255,255,0.08);
  --radius:      12px;
  --radius-lg:   16px;
  --shadow-card: 0 4px 24px rgba(0,0,0,0.35);
  --transition:  0.22s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--navy);
  -webkit-font-smoothing: antialiased;
  min-height: 100dvh;
}

/* ── Typography ── */
h1,h2,h3,h4,h5,h6 {
  line-height: 1.2;
  font-weight: 700;
  color: #fff;
}
p { color: var(--text-muted); }
a { color: inherit; text-decoration: none; }
a:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; border-radius: 4px; }

/* ── Layout ── */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.section {
  padding: 96px 0;
}
.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}
.section-subtitle {
  font-size: 1.05rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 0;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  padding: 12px 24px;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
  line-height: 1;
}
.btn:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }
.btn-primary {
  background: var(--green);
  color: #0D1B2A;
}
.btn-primary:hover {
  background: #7dd35b;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(108,194,74,0.35);
}
.btn-primary:active { transform: none; }
.btn-outline {
  background: transparent;
  color: #fff;
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn-outline:hover {
  border-color: var(--green);
  color: var(--green);
  background: rgba(108,194,74,0.06);
}
.btn-ghost {
  background: transparent;
  color: rgba(255,255,255,0.6);
  border: 1.5px solid rgba(255,255,255,0.12);
}
.btn-ghost:hover { color: #fff; border-color: rgba(255,255,255,0.3); }
.btn-lg { padding: 15px 32px; font-size: 0.95rem; border-radius: 14px; }
.btn-sm { padding: 8px 18px; font-size: 0.82rem; border-radius: 8px; }

/* ── Navbar ── */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 16px 0;
  transition: all 0.3s ease;
  background: transparent;
}
.navbar.scrolled {
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 12px 0;
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  color: rgba(255,255,255,0.75);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 8px;
  cursor: pointer;
  transition: all var(--transition);
  background: none;
  border: none;
  font-family: inherit;
  text-decoration: none;
}
.nav-link:hover { color: #fff; background: rgba(255,255,255,0.06); }
.nav-link.active { color: var(--green); }

/* ── Dropdown ── */
.nav-dropdown { position: relative; }
.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 200px;
  background: #1B2838;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  padding: 8px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: all 0.18s ease;
  box-shadow: 0 16px 48px rgba(0,0,0,0.5);
}
.dropdown-menu.open {
  opacity: 1;
  pointer-events: all;
  transform: none;
}
.dropdown-item {
  display: block;
  padding: 9px 14px;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.75);
  border-radius: 8px;
  transition: all 0.15s;
}
.dropdown-item:hover { color: #fff; background: rgba(255,255,255,0.07); }

/* ── Mobile Menu ── */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
}
.mobile-menu-btn:hover { background: rgba(255,255,255,0.08); }

/* ── Footer ── */
.footer {
  background: #080f1a;
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 72px 0 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-tagline {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.45);
  line-height: 1.6;
  margin-bottom: 24px;
}
.footer-portals { }
.footer-portal-link {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.45);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  padding: 4px 10px;
  transition: all 0.15s;
}
.footer-portal-link:hover { color: #fff; border-color: rgba(255,255,255,0.25); }
.footer-col-title {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color 0.15s;
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p { font-size: 0.82rem; color: rgba(255,255,255,0.35); }
.footer-regions {
  display: flex;
  gap: 20px;
  font-size: 0.78rem;
  color: rgba(255,255,255,0.3);
}

/* ── Page Hero (internal pages) ── */
.page-hero {
  padding: 160px 0 80px;
  background: linear-gradient(135deg, #0D1B2A 0%, #15295A 60%, #0D1B2A 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(108,194,74,0.05) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(108,194,74,0.05) 1px, transparent 1px);
  background-size: 60px 60px;
}
.page-hero-content { position: relative; z-index: 1; max-width: 700px; }
.page-hero h1 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  color: #fff;
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}
.page-hero p {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.7;
  max-width: 560px;
}

/* ── Cards & Surfaces ── */
.card {
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}
.card:hover {
  background: rgba(255,255,255,0.05);
  border-color: rgba(108,194,74,0.2);
}
.card-accent {
  border-top: 2px solid var(--green);
}

/* ── Stat Circles ── */
.stat-circles {
  display: flex;
  gap: 40px;
  justify-content: center;
  flex-wrap: wrap;
}
.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.stat-ring {
  width: 130px;
  height: 130px;
  position: relative;
}
.stat-ring svg { transform: rotate(-90deg); }
.stat-ring-bg { fill: none; stroke: rgba(255,255,255,0.07); stroke-width: 8; }
.stat-ring-fill { fill: none; stroke: var(--green); stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1s ease; }
.stat-ring-text {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.stat-ring-num {
  font-size: 1.6rem;
  font-weight: 800;
  color: #fff;
  line-height: 1;
}
.stat-ring-unit {
  font-size: 0.72rem;
  color: var(--green);
  font-weight: 600;
}
.stat-circle-label {
  text-align: center;
  font-size: 0.82rem;
  color: rgba(255,255,255,0.55);
  max-width: 120px;
  line-height: 1.4;
}

/* ── Accordion ── */
.accordion-item {
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 8px;
  transition: border-color var(--transition);
}
.accordion-item.open { border-color: rgba(108,194,74,0.3); }
.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px;
  background: rgba(255,255,255,0.03);
  border: none;
  color: #fff;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  transition: background var(--transition);
}
.accordion-header:hover { background: rgba(255,255,255,0.06); }
.accordion-item.open .accordion-header { background: rgba(108,194,74,0.07); }
.accordion-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  border-radius: 50%;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.25s ease;
}
.accordion-item.open .accordion-icon { transform: rotate(45deg); background: rgba(108,194,74,0.25); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.accordion-item.open .accordion-body { max-height: 300px; }
.accordion-body-inner {
  padding: 0 24px 24px;
  color: rgba(255,255,255,0.65);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ── Timeline ── */
.timeline { display: flex; flex-direction: column; gap: 0; }
.timeline-item {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 24px;
  align-items: center;
  padding: 20px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline-item:last-child { border-bottom: none; }
.timeline-duration {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--green);
  line-height: 1;
}
.timeline-duration span {
  display: block;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-top: 2px;
}
.timeline-bar-wrap { flex: 1; }
.timeline-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,0.8);
  margin-bottom: 8px;
}
.timeline-bar {
  height: 6px;
  background: rgba(255,255,255,0.07);
  border-radius: 100px;
  overflow: hidden;
}
.timeline-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--green), #4a9e35);
  border-radius: 100px;
  transition: width 1s ease;
}

/* ── Testimonials ── */
.testimonial-carousel { position: relative; }
.testimonial-track {
  display: flex;
  overflow: hidden;
}
.testimonial-slide {
  min-width: 100%;
  transition: transform 0.4s ease;
}
.testimonial-card {
  background: rgba(21,41,90,0.4);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius-lg);
  padding: 36px;
  max-width: 700px;
  margin: 0 auto;
}
.testimonial-quote {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.85);
  font-style: italic;
  line-height: 1.7;
  margin-bottom: 20px;
}
.testimonial-quote::before { content: '\201C'; color: var(--green); font-size: 1.4em; }
.testimonial-quote::after  { content: '\201D'; color: var(--green); font-size: 1.4em; }
.testimonial-author {
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(255,255,255,0.55);
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  padding: 0;
}
.dot.active { background: var(--green); width: 20px; border-radius: 4px; }
.dot:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }

/* ── Security/Integration Feature Lists ── */
.feature-list { display: flex; flex-direction: column; gap: 16px; }
.feature-row {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.feature-row:hover {
  background: rgba(108,194,74,0.04);
  border-color: rgba(108,194,74,0.15);
}
.feature-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 10px;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
}
.feature-text h4 { font-size: 0.95rem; font-weight: 600; color: #fff; margin-bottom: 4px; }
.feature-text p { font-size: 0.85rem; color: rgba(255,255,255,0.55); line-height: 1.5; }

/* ── Check list ── */
.check-list { list-style: none; display: flex; flex-direction: column; gap: 14px; }
.check-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.9rem;
  color: rgba(255,255,255,0.75);
  line-height: 1.5;
}
.check-list li::before {
  content: '';
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  background-image: url("data:image/svg+xml,%3Csvg width='12' height='9' viewBox='0 0 12 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 4l3.5 3.5L11 1' stroke='%236CC24A' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: center;
  margin-top: 1px;
}

/* ── Demo Form ── */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.form-field { display: flex; flex-direction: column; gap: 6px; }
.form-field.full { grid-column: 1 / -1; }
.form-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(255,255,255,0.7);
  letter-spacing: 0.02em;
}
.form-label .required { color: var(--green); margin-left: 2px; }
.form-input {
  width: 100%;
  padding: 12px 16px;
  background: rgba(255,255,255,0.05);
  border: 1.5px solid rgba(255,255,255,0.12);
  border-radius: 10px;
  color: #fff;
  font-family: inherit;
  font-size: 0.9rem;
  transition: all var(--transition);
  outline: none;
}
.form-input:focus {
  border-color: var(--green);
  background: rgba(108,194,74,0.05);
  box-shadow: 0 0 0 3px rgba(108,194,74,0.12);
}
.form-input::placeholder { color: rgba(255,255,255,0.3); }
.form-input.error { border-color: #ef4444; }
.form-error {
  font-size: 0.78rem;
  color: #ef4444;
  display: none;
}
.form-error.visible { display: block; }
textarea.form-input { resize: vertical; min-height: 100px; }
select.form-input { cursor: pointer; }
select.form-input option { background: #1B2838; color: #fff; }

/* ── Grid helpers ── */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: start; }
.three-col { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .two-col { gap: 40px; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .mobile-menu-btn { display: block; }
  .nav-links {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: rgba(13,27,42,0.98);
    backdrop-filter: blur(16px);
    border-bottom: 1px solid rgba(255,255,255,0.08);
    flex-direction: column;
    padding: 16px 24px 24px;
    gap: 4px;
  }
  .nav-links.open { display: flex; }
  .nav-links .btn { width: 100%; justify-content: center; }
  .nav-dropdown { width: 100%; }
  .dropdown-menu {
    position: static;
    opacity: 1;
    pointer-events: all;
    transform: none;
    box-shadow: none;
    background: rgba(255,255,255,0.04);
    margin-top: 4px;
  }
  .two-col { grid-template-columns: 1fr; }
  .three-col { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1/-1; }
  .stat-circles { gap: 24px; }
  .timeline-item { grid-template-columns: 80px 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .stat-circles { flex-direction: column; align-items: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ── WellStream Platform — Shared Styles ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:        #0D1B2A;
  --navy-mid:    #15295A;
  --navy-light:  #1B2838;
  --green:       #6CC24A;
  --green-dark:  #4a9e35;
  --gray-dark:   #3C424B;
  --text-primary: #ffffff;
  --text-muted:  rgba(255,255,255,0.6);
  --border:      rgba(255,255,255,0.08);
  --radius:      12px;
  --radius-lg:   16px;
  --shadow-card: 0 4px 24px rgba(0,0,0,0.35);
  --transition:  0.22s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--navy);
  -webkit-font-smoothing: antialiased;
  min-height: 100dvh;
}

/* ── Typography ── */
h1,h2,h3,h4,h5,h6 {
  line-height: 1.2;
  font-weight: 700;
  color: #fff;
}
p { color: var(--text-muted); }
a { color: inherit; text-decoration: none; }
a:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; border-radius: 4px; }

/* ── Layout ── */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.section {
  padding: 96px 0;
}
.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}
.section-subtitle {
  font-size: 1.05rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 0;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  padding: 12px 24px;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
  line-height: 1;
}
.btn:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }
.btn-primary {
  background: var(--green);
  color: #0D1B2A;
}
.btn-primary:hover {
  background: #7dd35b;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(108,194,74,0.35);
}
.btn-primary:active { transform: none; }
.btn-outline {
  background: transparent;
  color: #fff;
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn-outline:hover {
  border-color: var(--green);
  color: var(--green);
  background: rgba(108,194,74,0.06);
}
.btn-ghost {
  background: transparent;
  color: rgba(255,255,255,0.6);
  border: 1.5px solid rgba(255,255,255,0.12);
}
.btn-ghost:hover { color: #fff; border-color: rgba(255,255,255,0.3); }
.btn-lg { padding: 15px 32px; font-size: 0.95rem; border-radius: 14px; }
.btn-sm { padding: 8px 18px; font-size: 0.82rem; border-radius: 8px; }

/* ── Navbar ── */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 16px 0;
  transition: all 0.3s ease;
  background: transparent;
}
.navbar.scrolled {
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 12px 0;
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  color: rgba(255,255,255,0.75);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 8px;
  cursor: pointer;
  transition: all var(--transition);
  background: none;
  border: none;
  font-family: inherit;
  text-decoration: none;
}
.nav-link:hover { color: #fff; background: rgba(255,255,255,0.06); }
.nav-link.active { color: var(--green); }

/* ── Dropdown ── */
.nav-dropdown { position: relative; }
.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 200px;
  background: #1B2838;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  padding: 8px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: all 0.18s ease;
  box-shadow: 0 16px 48px rgba(0,0,0,0.5);
}
.dropdown-menu.open {
  opacity: 1;
  pointer-events: all;
  transform: none;
}
.dropdown-item {
  display: block;
  padding: 9px 14px;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.75);
  border-radius: 8px;
  transition: all 0.15s;
}
.dropdown-item:hover { color: #fff; background: rgba(255,255,255,0.07); }

/* ── Mobile Menu ── */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
}
.mobile-menu-btn:hover { background: rgba(255,255,255,0.08); }

/* ── Footer ── */
.footer {
  background: #080f1a;
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 72px 0 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-tagline {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.45);
  line-height: 1.6;
  margin-bottom: 24px;
}
.footer-portals { }
.footer-portal-link {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.45);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  padding: 4px 10px;
  transition: all 0.15s;
}
.footer-portal-link:hover { color: #fff; border-color: rgba(255,255,255,0.25); }
.footer-col-title {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color 0.15s;
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p { font-size: 0.82rem; color: rgba(255,255,255,0.35); }
.footer-regions {
  display: flex;
  gap: 20px;
  font-size: 0.78rem;
  color: rgba(255,255,255,0.3);
}

/* ── Page Hero (internal pages) ── */
.page-hero {
  padding: 160px 0 80px;
  background: linear-gradient(135deg, #0D1B2A 0%, #15295A 60%, #0D1B2A 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(108,194,74,0.05) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(108,194,74,0.05) 1px, transparent 1px);
  background-size: 60px 60px;
}
.page-hero-content { position: relative; z-index: 1; max-width: 700px; }
.page-hero h1 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  color: #fff;
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}
.page-hero p {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.7;
  max-width: 560px;
}

/* ── Cards & Surfaces ── */
.card {
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}
.card:hover {
  background: rgba(255,255,255,0.05);
  border-color: rgba(108,194,74,0.2);
}
.card-accent {
  border-top: 2px solid var(--green);
}

/* ── Stat Circles ── */
.stat-circles {
  display: flex;
  gap: 40px;
  justify-content: center;
  flex-wrap: wrap;
}
.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.stat-ring {
  width: 130px;
  height: 130px;
  position: relative;
}
.stat-ring svg { transform: rotate(-90deg); }
.stat-ring-bg { fill: none; stroke: rgba(255,255,255,0.07); stroke-width: 8; }
.stat-ring-fill { fill: none; stroke: var(--green); stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1s ease; }
.stat-ring-text {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.stat-ring-num {
  font-size: 1.6rem;
  font-weight: 800;
  color: #fff;
  line-height: 1;
}
.stat-ring-unit {
  font-size: 0.72rem;
  color: var(--green);
  font-weight: 600;
}
.stat-circle-label {
  text-align: center;
  font-size: 0.82rem;
  color: rgba(255,255,255,0.55);
  max-width: 120px;
  line-height: 1.4;
}

/* ── Accordion ── */
.accordion-item {
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 8px;
  transition: border-color var(--transition);
}
.accordion-item.open { border-color: rgba(108,194,74,0.3); }
.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px;
  background: rgba(255,255,255,0.03);
  border: none;
  color: #fff;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  transition: background var(--transition);
}
.accordion-header:hover { background: rgba(255,255,255,0.06); }
.accordion-item.open .accordion-header { background: rgba(108,194,74,0.07); }
.accordion-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  border-radius: 50%;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.25s ease;
}
.accordion-item.open .accordion-icon { transform: rotate(45deg); background: rgba(108,194,74,0.25); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.accordion-item.open .accordion-body { max-height: 300px; }
.accordion-body-inner {
  padding: 0 24px 24px;
  color: rgba(255,255,255,0.65);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ── Timeline ── */
.timeline { display: flex; flex-direction: column; gap: 0; }
.timeline-item {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 24px;
  align-items: center;
  padding: 20px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline-item:last-child { border-bottom: none; }
.timeline-duration {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--green);
  line-height: 1;
}
.timeline-duration span {
  display: block;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-top: 2px;
}
.timeline-bar-wrap { flex: 1; }
.timeline-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,0.8);
  margin-bottom: 8px;
}
.timeline-bar {
  height: 6px;
  background: rgba(255,255,255,0.07);
  border-radius: 100px;
  overflow: hidden;
}
.timeline-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--green), #4a9e35);
  border-radius: 100px;
  transition: width 1s ease;
}

/* ── Testimonials ── */
.testimonial-carousel { position: relative; }
.testimonial-track {
  display: flex;
  overflow: hidden;
}
.testimonial-slide {
  min-width: 100%;
  transition: transform 0.4s ease;
}
.testimonial-card {
  background: rgba(21,41,90,0.4);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius-lg);
  padding: 36px;
  max-width: 700px;
  margin: 0 auto;
}
.testimonial-quote {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.85);
  font-style: italic;
  line-height: 1.7;
  margin-bottom: 20px;
}
.testimonial-quote::before { content: '\201C'; color: var(--green); font-size: 1.4em; }
.testimonial-quote::after  { content: '\201D'; color: var(--green); font-size: 1.4em; }
.testimonial-author {
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(255,255,255,0.55);
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  padding: 0;
}
.dot.active { background: var(--green); width: 20px; border-radius: 4px; }
.dot:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }

/* ── Security/Integration Feature Lists ── */
.feature-list { display: flex; flex-direction: column; gap: 16px; }
.feature-row {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.feature-row:hover {
  background: rgba(108,194,74,0.04);
  border-color: rgba(108,194,74,0.15);
}
.feature-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 10px;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
}
.feature-text h4 { font-size: 0.95rem; font-weight: 600; color: #fff; margin-bottom: 4px; }
.feature-text p { font-size: 0.85rem; color: rgba(255,255,255,0.55); line-height: 1.5; }

/* ── Check list ── */
.check-list { list-style: none; display: flex; flex-direction: column; gap: 14px; }
.check-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.9rem;
  color: rgba(255,255,255,0.75);
  line-height: 1.5;
}
.check-list li::before {
  content: '';
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  background-image: url("data:image/svg+xml,%3Csvg width='12' height='9' viewBox='0 0 12 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 4l3.5 3.5L11 1' stroke='%236CC24A' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: center;
  margin-top: 1px;
}

/* ── Demo Form ── */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.form-field { display: flex; flex-direction: column; gap: 6px; }
.form-field.full { grid-column: 1 / -1; }
.form-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(255,255,255,0.7);
  letter-spacing: 0.02em;
}
.form-label .required { color: var(--green); margin-left: 2px; }
.form-input {
  width: 100%;
  padding: 12px 16px;
  background: rgba(255,255,255,0.05);
  border: 1.5px solid rgba(255,255,255,0.12);
  border-radius: 10px;
  color: #fff;
  font-family: inherit;
  font-size: 0.9rem;
  transition: all var(--transition);
  outline: none;
}
.form-input:focus {
  border-color: var(--green);
  background: rgba(108,194,74,0.05);
  box-shadow: 0 0 0 3px rgba(108,194,74,0.12);
}
.form-input::placeholder { color: rgba(255,255,255,0.3); }
.form-input.error { border-color: #ef4444; }
.form-error {
  font-size: 0.78rem;
  color: #ef4444;
  display: none;
}
.form-error.visible { display: block; }
textarea.form-input { resize: vertical; min-height: 100px; }
select.form-input { cursor: pointer; }
select.form-input option { background: #1B2838; color: #fff; }

/* ── Grid helpers ── */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: start; }
.three-col { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .two-col { gap: 40px; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .mobile-menu-btn { display: block; }
  .nav-links {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: rgba(13,27,42,0.98);
    backdrop-filter: blur(16px);
    border-bottom: 1px solid rgba(255,255,255,0.08);
    flex-direction: column;
    padding: 16px 24px 24px;
    gap: 4px;
  }
  .nav-links.open { display: flex; }
  .nav-links .btn { width: 100%; justify-content: center; }
  .nav-dropdown { width: 100%; }
  .dropdown-menu {
    position: static;
    opacity: 1;
    pointer-events: all;
    transform: none;
    box-shadow: none;
    background: rgba(255,255,255,0.04);
    margin-top: 4px;
  }
  .two-col { grid-template-columns: 1fr; }
  .three-col { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1/-1; }
  .stat-circles { gap: 24px; }
  .timeline-item { grid-template-columns: 80px 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .stat-circles { flex-direction: column; align-items: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

raw_arguments.content:
/* ── WellStream Platform — Shared Styles ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:        #0D1B2A;
  --navy-mid:    #15295A;
  --navy-light:  #1B2838;
  --green:       #6CC24A;
  --green-dark:  #4a9e35;
  --gray-dark:   #3C424B;
  --text-primary: #ffffff;
  --text-muted:  rgba(255,255,255,0.6);
  --border:      rgba(255,255,255,0.08);
  --radius:      12px;
  --radius-lg:   16px;
  --shadow-card: 0 4px 24px rgba(0,0,0,0.35);
  --transition:  0.22s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--navy);
  -webkit-font-smoothing: antialiased;
  min-height: 100dvh;
}

/* ── Typography ── */
h1,h2,h3,h4,h5,h6 {
  line-height: 1.2;
  font-weight: 700;
  color: #fff;
}
p { color: var(--text-muted); }
a { color: inherit; text-decoration: none; }
a:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; border-radius: 4px; }

/* ── Layout ── */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.section {
  padding: 96px 0;
}
.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}
.section-subtitle {
  font-size: 1.05rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 0;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  padding: 12px 24px;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
  line-height: 1;
}
.btn:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }
.btn-primary {
  background: var(--green);
  color: #0D1B2A;
}
.btn-primary:hover {
  background: #7dd35b;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(108,194,74,0.35);
}
.btn-primary:active { transform: none; }
.btn-outline {
  background: transparent;
  color: #fff;
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn-outline:hover {
  border-color: var(--green);
  color: var(--green);
  background: rgba(108,194,74,0.06);
}
.btn-ghost {
  background: transparent;
  color: rgba(255,255,255,0.6);
  border: 1.5px solid rgba(255,255,255,0.12);
}
.btn-ghost:hover { color: #fff; border-color: rgba(255,255,255,0.3); }
.btn-lg { padding: 15px 32px; font-size: 0.95rem; border-radius: 14px; }
.btn-sm { padding: 8px 18px; font-size: 0.82rem; border-radius: 8px; }

/* ── Navbar ── */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 16px 0;
  transition: all 0.3s ease;
  background: transparent;
}
.navbar.scrolled {
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 12px 0;
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  color: rgba(255,255,255,0.75);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 8px;
  cursor: pointer;
  transition: all var(--transition);
  background: none;
  border: none;
  font-family: inherit;
  text-decoration: none;
}
.nav-link:hover { color: #fff; background: rgba(255,255,255,0.06); }
.nav-link.active { color: var(--green); }

/* ── Dropdown ── */
.nav-dropdown { position: relative; }
.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 200px;
  background: #1B2838;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  padding: 8px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: all 0.18s ease;
  box-shadow: 0 16px 48px rgba(0,0,0,0.5);
}
.dropdown-menu.open {
  opacity: 1;
  pointer-events: all;
  transform: none;
}
.dropdown-item {
  display: block;
  padding: 9px 14px;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.75);
  border-radius: 8px;
  transition: all 0.15s;
}
.dropdown-item:hover { color: #fff; background: rgba(255,255,255,0.07); }

/* ── Mobile Menu ── */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
}
.mobile-menu-btn:hover { background: rgba(255,255,255,0.08); }

/* ── Footer ── */
.footer {
  background: #080f1a;
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 72px 0 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-tagline {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.45);
  line-height: 1.6;
  margin-bottom: 24px;
}
.footer-portals { }
.footer-portal-link {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.45);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  padding: 4px 10px;
  transition: all 0.15s;
}
.footer-portal-link:hover { color: #fff; border-color: rgba(255,255,255,0.25); }
.footer-col-title {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color 0.15s;
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p { font-size: 0.82rem; color: rgba(255,255,255,0.35); }
.footer-regions {
  display: flex;
  gap: 20px;
  font-size: 0.78rem;
  color: rgba(255,255,255,0.3);
}

/* ── Page Hero (internal pages) ── */
.page-hero {
  padding: 160px 0 80px;
  background: linear-gradient(135deg, #0D1B2A 0%, #15295A 60%, #0D1B2A 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(108,194,74,0.05) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(108,194,74,0.05) 1px, transparent 1px);
  background-size: 60px 60px;
}
.page-hero-content { position: relative; z-index: 1; max-width: 700px; }
.page-hero h1 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  color: #fff;
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}
.page-hero p {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.7;
  max-width: 560px;
}

/* ── Cards & Surfaces ── */
.card {
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}
.card:hover {
  background: rgba(255,255,255,0.05);
  border-color: rgba(108,194,74,0.2);
}
.card-accent {
  border-top: 2px solid var(--green);
}

/* ── Stat Circles ── */
.stat-circles {
  display: flex;
  gap: 40px;
  justify-content: center;
  flex-wrap: wrap;
}
.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.stat-ring {
  width: 130px;
  height: 130px;
  position: relative;
}
.stat-ring svg { transform: rotate(-90deg); }
.stat-ring-bg { fill: none; stroke: rgba(255,255,255,0.07); stroke-width: 8; }
.stat-ring-fill { fill: none; stroke: var(--green); stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1s ease; }
.stat-ring-text {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.stat-ring-num {
  font-size: 1.6rem;
  font-weight: 800;
  color: #fff;
