<script>
  // Navbar scroll
  const navbar = document.getElementById('navbar');
  window.addEventListener('scroll', () => {
    navbar.classList.toggle('scrolled', window.scrollY > 30);
  }, { passive: true });
  if (window.scrollY <= 30) navbar.classList.add('scrolled');

  // Mobile menu
  const mobileBtn = document.getElementById('mobileMenuBtn');
  const navLinks = document.getElementById('navLinks');
  mobileBtn.addEventListener('click', () => {
    const open = navLinks.classList.toggle('open');
    mobileBtn.setAttribute('aria-expanded', open);
  });

  // Dropdown
  document.querySelectorAll('.dropdown-toggle').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !expanded);
      btn.nextElementSibling.classList.toggle('open');
    });
  });
  document.addEventListener('click', () => {
    document.querySelectorAll('.dropdown-menu.open').forEach(m => m.classList.remove('open'));
    document.querySelectorAll('.dropdown-toggle').forEach(b => b.setAttribute('aria-expanded','false'));
  });

  // Accordion
  document.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', () => {
      const item = header.closest('.accordion-item');
      const isOpen = item.classList.contains('open');
      document.querySelectorAll('.accordion-item').forEach(i => {
        i.classList.remove('open');
        i.querySelector('.accordion-header').setAttribute('aria-expanded','false');
      });
      if (!isOpen) {
        item.classList.add('open');
        header.setAttribute('aria-expanded','true');
      }
    });
  });

  // Testimonial Carousel
  let currentSlide = 0;
  const track = document.getElementById('testimonialTrack');
  const slides = track.querySelectorAll('.testimonial-slide');
  const dots = document.querySelectorAll('.dot');

  function goToSlide(n) {
    currentSlide = n;
    track.style.transform = `translateX(-${n * 100}%)`;
    slides.forEach((s, i) => s.setAttribute('aria-hidden', i !== n));
    dots.forEach((d, i) => {
      d.classList.toggle('active', i === n);
    });
  }

  dots.forEach(dot => {
    dot.addEventListener('click', () => goToSlide(parseInt(dot.dataset.slide)));
  });

  // Auto-advance testimonials
  let autoSlide = setInterval(() => goToSlide((currentSlide + 1) % slides.length), 5000);
  track.addEventListener('mouseenter', () => clearInterval(autoSlide));
  track.addEventListener('mouseleave', () => {
    autoSlide = setInterval(() => goToSlide((currentSlide + 1) % slides.length), 5000);
  });

  // Animate stat rings on scroll
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.querySelectorAll('.stat-ring-fill').forEach(ring => {
          const target = parseFloat(ring.dataset.target);
          ring.style.strokeDashoffset = target;
        });
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });
  document.querySelectorAll('.stat-circles').forEach(el => observer.observe(el));
</script>
