<script>
  // Navbar
  const navbar = document.getElementById('navbar');
  window.addEventListener('scroll', () => {
    navbar.classList.toggle('scrolled', window.scrollY > 30);
  }, { passive: true });

  // Mobile menu
  const mobileBtn = document.getElementById('mobileMenuBtn');
  const navLinks = document.getElementById('navLinks');
  mobileBtn.addEventListener('click', () => {
    const open = navLinks.classList.toggle('open');
    mobileBtn.setAttribute('aria-expanded', open);
  });

  // Dropdown
  document.querySelectorAll('.dropdown-toggle').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !expanded);
      btn.nextElementSibling.classList.toggle('open');
    });
  });
  document.addEventListener('click', () => {
    document.querySelectorAll('.dropdown-menu.open').forEach(m => m.classList.remove('open'));
    document.querySelectorAll('.dropdown-toggle').forEach(b => b.setAttribute('aria-expanded','false'));
  });

  // Form validation
  const form = document.getElementById('demoForm');
  const submitBtn = document.getElementById('submitBtn');
  const submitText = document.getElementById('submitText');
  const submitSpinner = document.getElementById('submitSpinner');
  const formSuccess = document.getElementById('formSuccess');
  const errorSummary = document.getElementById('errorSummary');

  const requiredFields = [
    { id: 'firstName', errId: 'firstName-error' },
    { id: 'lastName',  errId: 'lastName-error' },
    { id: 'email',     errId: 'email-error' },
    { id: 'company',   errId: 'company-error' },
    { id: 'jobTitle',  errId: 'jobTitle-error' },
    { id: 'country',   errId: 'country-error' },
  ];

  function validateEmail(val) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
  }

  function clearError(fieldId, errId) {
    const el = document.getElementById(fieldId);
    const err = document.getElementById(errId);
    el.classList.remove('error');
    err.classList.remove('visible');
    el.removeAttribute('aria-describedby');
  }

  // Inline validation on blur
  requiredFields.forEach(({ id, errId }) => {
    document.getElementById(id).addEventListener('blur', () => {
      const el = document.getElementById(id);
      const err = document.getElementById(errId);
      const val = el.value.trim();
      let invalid = !val;
      if (id === 'email' && val) invalid = !validateEmail(val);
      if (invalid) {
        el.classList.add('error');
        err.classList.add('visible');
        el.setAttribute('aria-describedby', errId);
      } else {
        clearError(id, errId);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    let hasError = false;

    requiredFields.forEach(({ id, errId }) => {
      const el = document.getElementById(id);
      const err = document.getElementById(errId);
      const val = el.value.trim();
      let invalid = !val;
      if (id === 'email' && val) invalid = !validateEmail(val);
      if (invalid) {
        el.classList.add('error');
        err.classList.add('visible');
        el.setAttribute('aria-describedby', errId);
        hasError = true;
      } else {
        clearError(id, errId);
      }
    });

    if (hasError) {
      errorSummary.style.display = 'block';
      // Focus first error field
      const firstErr = requiredFields.find(({ id }) => {
        const el = document.getElementById(id);
        return el.classList.contains('error');
      });
      if (firstErr) document.getElementById(firstErr.id).focus();
      return;
    }

    errorSummary.style.display = 'none';

    // Simulate submission
    submitBtn.disabled = true;
    submitText.style.display = 'none';
    submitSpinner.style.display = 'block';
    submitBtn.setAttribute('aria-busy', 'true');

    setTimeout(() => {
      form.style.display = 'none';
      formSuccess.classList.add('visible');
      formSuccess.querySelector('h3').focus();
    }, 1400);
  });
</script>
</body>
